export default function LogoSvg() {
    return (
        <svg
            viewBox="0 0 1024 1024"
            className="w-full h-full"
            xmlns="http://www.w3.org/2000/svg"
        >
            {paths.map((path, index) => (
                <motion.path
                    key={path.id}
                    d={path.d}
                    transform={path.transform}
                    initial={{ pathLength: 0, fillOpacity: 0, strokeOpacity: 1 }}
                    animate={{ pathLength: 1, fillOpacity: 1, strokeOpacity: 0 }}
                    transition={{
                        pathLength: { duration: 2, ease: "easeInOut", delay: index * 0.0008423180592991914 },
                        fillOpacity: { duration: 1, ease: "easeOut", delay: 1.5 + index * 0.0008423180592991914 },
                        strokeOpacity: { duration: 0.5, ease: "easeOut", delay: 2 + index * 0.0008423180592991914 }
                    }}
                    stroke={path.fill} 
                    strokeWidth="2"
                    fill={path.fill}
                />
            ))}
        </svg>
    )
}
